const GAME_STAGE_CLASS = 'subei-game-stage';
const COMPANION_LAYER_CLASS = 'subei-game-companion-layer';
const STATIC_COMPANION_SELECTORS = ['#st-chatu8-settings', '#st-chatu8-ai-dialog', '#st-chatu8-fab'] as const;

type FullscreenListener = (active: boolean) => void;

type PortalRecord = {
  element: HTMLElement;
  placeholder: Comment;
};

type FullscreenSession = {
  document: Document;
  host: HTMLIFrameElement;
  stage: HTMLElement;
  companionLayer: HTMLElement;
  portals: Map<HTMLElement, PortalRecord>;
  observer: MutationObserver | null;
  onFullscreenChange: () => void;
  active: boolean;
  request: Promise<void> | null;
};

let session: FullscreenSession | null = null;
let reportedActive = false;
const listeners = new Set<FullscreenListener>();

function reportActive(active: boolean) {
  if (reportedActive === active) return;
  reportedActive = active;
  for (const listener of listeners) listener(active);
}

function fullscreenError(error: unknown): Error {
  const detail = error instanceof Error ? error.message : String(error);
  return Error(detail ? `浏览器拒绝了游戏原生全屏：${detail}` : '浏览器拒绝了游戏原生全屏');
}

function resolveStage(host: HTMLIFrameElement): HTMLElement {
  const stage = host.parentElement;
  if (!stage?.classList.contains('mes_streaming')) {
    throw Error('找不到仅承载游戏画面的全屏舞台');
  }
  if (![...stage.querySelectorAll(':scope > iframe')].every(frame => frame === host)) {
    throw Error('游戏舞台中存在未知 iframe，已取消全屏申请');
  }
  return stage;
}

function isZhihuijiRoot(element: Element): element is HTMLElement {
  const identity = `${element.id} ${typeof element.className === 'string' ? element.className : ''}`;
  if (/(^|\s)st-chatu8(?:-|\s|$)/i.test(identity)) return true;
  if (/^ch-(?:entry|regex)-/i.test(element.id)) return true;
  return false;
}

function asHtmlElement(node: Node): HTMLElement | null {
  return node.nodeType === 1 && 'matches' in node ? (node as HTMLElement) : null;
}

function portalElement(current: FullscreenSession, element: HTMLElement) {
  if (!element.isConnected || current.stage.contains(element) || element.contains(current.stage)) return;

  const existing = current.portals.get(element);
  if (existing) {
    current.companionLayer.appendChild(element);
    return;
  }

  const parent = element.parentNode;
  if (!parent) return;
  const placeholder = current.document.createComment(`苏北乡村全屏占位:${element.id || element.tagName}`);
  parent.insertBefore(placeholder, element);
  current.companionLayer.appendChild(element);
  current.portals.set(element, { element, placeholder });
}

function restorePortals(current: FullscreenSession) {
  for (const { element, placeholder } of current.portals.values()) {
    const placeholderParent = placeholder.parentNode;
    if (!placeholderParent) continue;

    if (element.isConnected && current.companionLayer.contains(element)) {
      placeholderParent.replaceChild(element, placeholder);
    } else {
      placeholder.remove();
    }
  }
  current.portals.clear();
}

function findPlaceholder(document: Document, label: string): Comment | null {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_COMMENT);
  let node: Node | null;
  while ((node = walker.nextNode())) {
    if ((node as Comment).data === label) return node as Comment;
  }
  return null;
}

/**
 * 开发热重载可能发生在一次未完成的申请之后；恢复旧模块留下的门户，避免重复层或节点丢失。
 */
function recoverOrphanedLayers(document: Document, stage: HTMLElement) {
  const layers = [...stage.querySelectorAll<HTMLElement>(`:scope > .${COMPANION_LAYER_CLASS}`)];
  let restored = 0;
  for (const layer of layers) {
    for (const element of [...layer.children] as HTMLElement[]) {
      const label = `苏北乡村全屏占位:${element.id || element.tagName}`;
      const placeholder = findPlaceholder(document, label);
      if (placeholder?.parentNode) placeholder.parentNode.replaceChild(element, placeholder);
      else document.body.appendChild(element);
      restored += 1;
    }
    layer.remove();
  }
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_COMMENT);
  const stalePlaceholders: Comment[] = [];
  let node: Node | null;
  while ((node = walker.nextNode())) {
    const comment = node as Comment;
    if (comment.data.startsWith('苏北乡村全屏占位:')) stalePlaceholders.push(comment);
  }
  for (const placeholder of stalePlaceholders) placeholder.remove();
  stage.classList.remove(GAME_STAGE_CLASS);
  if (layers.length > 0 || restored > 0 || stalePlaceholders.length > 0) {
    console.info('[苏北乡村] 已恢复热重载遗留的全屏门户', {
      layers: layers.length,
      restored,
      placeholders: stalePlaceholders.length,
    });
  }
}

function cleanupSession(current: FullscreenSession) {
  if (session !== current) return;
  current.observer?.disconnect();
  current.document.removeEventListener('fullscreenchange', current.onFullscreenChange);
  restorePortals(current);
  current.companionLayer.remove();
  current.stage.classList.remove(GAME_STAGE_CLASS);
  session = null;
  reportActive(false);
}

function prepareSession(host: HTMLIFrameElement): FullscreenSession {
  const document = host.ownerDocument;
  const stage = resolveStage(host);
  recoverOrphanedLayers(document, stage);
  const companionLayer = document.createElement('div');
  companionLayer.className = COMPANION_LAYER_CLASS;
  companionLayer.dataset.subeiFullscreenCompanions = '';
  stage.classList.add(GAME_STAGE_CLASS);
  stage.appendChild(companionLayer);

  const current = {
    document,
    host,
    stage,
    companionLayer,
    portals: new Map<HTMLElement, PortalRecord>(),
    observer: null,
    onFullscreenChange: () => undefined,
    active: false,
    request: null,
  } satisfies FullscreenSession;

  try {
    for (const selector of STATIC_COMPANION_SELECTORS) {
      const element = document.querySelector<HTMLElement>(selector);
      if (element) portalElement(current, element);
    }
    for (const element of [...document.body.children]) {
      if (element !== stage && !element.contains(stage) && isZhihuijiRoot(element)) portalElement(current, element);
    }

    const MutationObserverConstructor = document.defaultView?.MutationObserver ?? MutationObserver;
    current.observer = new MutationObserverConstructor(records => {
      for (const record of records) {
        if (record.type === 'attributes') {
          const element = asHtmlElement(record.target);
          if (element?.parentElement === document.body && isZhihuijiRoot(element)) {
            portalElement(current, element);
          }
          continue;
        }

        for (const node of record.addedNodes) {
          const element = asHtmlElement(node);
          if (element?.parentElement === document.body && isZhihuijiRoot(element)) {
            portalElement(current, element);
          }
        }
      }
    });
    current.observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['id', 'class'],
    });

    current.onFullscreenChange = () => {
      if (session !== current) return;
      const active = document.fullscreenElement === stage;
      current.active = active;
      if (active) reportActive(true);
      else cleanupSession(current);
    };
    document.addEventListener('fullscreenchange', current.onFullscreenChange);
    return current;
  } catch (error) {
    current.observer?.disconnect();
    restorePortals(current);
    companionLayer.remove();
    stage.classList.remove(GAME_STAGE_CLASS);
    throw error;
  }
}

export function subscribeGameFullscreen(listener: FullscreenListener): () => void {
  listeners.add(listener);
  listener(reportedActive);
  return () => listeners.delete(listener);
}

export function recoverGameFullscreen(host: HTMLIFrameElement) {
  if (session) return;
  const document = host.ownerDocument;
  if (document.fullscreenElement) return;
  recoverOrphanedLayers(document, resolveStage(host));
}

export function isGameFullscreenActive(host?: HTMLIFrameElement | null): boolean {
  if (!session?.active || session.document.fullscreenElement !== session.stage) return false;
  return !host || session.host === host;
}

/**
 * 必须直接从游戏按钮的受信任 click 处理函数调用。
 * requestFullscreen 在本函数返回 Promise 前同步执行，不能放进定时器或消息回调。
 */
export function requestGameFullscreen(host: HTMLIFrameElement): Promise<void> {
  const document = host.ownerDocument;
  if (document.fullscreenElement) {
    if (session?.stage === document.fullscreenElement && session.host === host) return Promise.resolve();
    return Promise.reject(Error('当前已有其他元素处于原生全屏，请先退出后重试'));
  }
  if (session) {
    if (session.host === host && session.request) return session.request;
    cleanupSession(session);
  }

  let current: FullscreenSession;
  try {
    current = prepareSession(host);
    session = current;
  } catch (error) {
    return Promise.reject(error);
  }

  let request: Promise<void>;
  try {
    request = current.stage.requestFullscreen({ navigationUI: 'hide' });
  } catch (error) {
    cleanupSession(current);
    return Promise.reject(fullscreenError(error));
  }

  current.request = request
    .then(() => {
      if (document.fullscreenElement !== current.stage) {
        throw Error('浏览器未将专用游戏舞台设为 fullscreenElement');
      }
      current.active = true;
      reportActive(true);
      console.info('[苏北乡村] 已进入游戏原生全屏');
    })
    .catch(error => {
      if (document.fullscreenElement !== current.stage) cleanupSession(current);
      throw fullscreenError(error);
    });
  return current.request;
}

export function exitGameFullscreen(): Promise<void> {
  const current = session;
  if (!current) return Promise.resolve();
  if (current.document.fullscreenElement !== current.stage) {
    cleanupSession(current);
    return Promise.resolve();
  }

  return current.document.exitFullscreen().then(() => {
    if (session === current && current.document.fullscreenElement !== current.stage) cleanupSession(current);
    console.info('[苏北乡村] 已退出游戏原生全屏');
  });
}

export function disposeGameFullscreen() {
  const current = session;
  if (!current) return;
  if (current.document.fullscreenElement === current.stage) {
    void current.document.exitFullscreen().catch(error => {
      console.warn('[苏北乡村] 卸载时退出游戏原生全屏失败', error);
    });
  } else {
    cleanupSession(current);
  }
}
