a(3, 7, 18, 0.92);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n/* 游戏壳顶栏：移动端只保留必要信息，完整天气与节令仍可点击世界信息查看。 */\n.game-header {\n  display: flex;\n  min-height: 64px;\n  align-items: center;\n  gap: 12px;\n  padding: 8px 32px;\n}\n\n.world-clock-card,\n.world-location,\n.header-icon-button {\n  border: 1px solid rgba(51, 65, 85, 0.8);\n  background: rgba(15, 23, 42, 0.82);\n  color: #cbd5e1;\n}\n\n.world-clock-card {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  gap: 10px;\n  min-width: 168px;\n  padding: 7px 12px;\n  border-radius: 12px;\n  text-align: left;\n}\n\n.world-clock-copy,\n.wallet-copy {\n  display: flex;\n  min-width: 0;\n  flex-direction: column;\n}\n\n.world-clock-copy strong {\n  color: #f1f5f9;\n  font: 800 15px/1.05 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n}\n\n.world-clock-copy small {\n  margin-top: 3px;\n  color: #67e8f9;\n  font: 600 10px/1.1 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  white-space: nowrap;\n}\n\n.world-context {\n  display: flex;\n  min-width: 0;\n  flex: 1 1 auto;\n  align-items: center;\n  gap: 10px;\n}\n\n.world-location {\n  display: flex;\n  min-width: 0;\n  max-width: 360px;\n  align-items: center;\n  gap: 8px;\n  padding: 9px 12px;\n  border-radius: 12px;\n}\n\n.world-location span {\n  overflow: hidden;\n  font: 600 14px/1.2 ui-serif, Georgia, 'Songti SC', serif;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.world-secondary {\n  display: flex;\n  min-width: 0;\n  align-items: center;\n  gap: 8px;\n  color: #cbd5e1;\n  font-size: 13px;\n}\n\n.world-secondary span {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  white-space: nowrap;\n}\n\n.header-actions {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  gap: 8px;\n}\n\n.wallet-compact {\n  display: flex;\n  min-width: 136px;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 6px 10px;\n  border: 1px solid rgba(245, 158, 11, 0.55);\n  border-radius: 14px;\n  background: linear-gradient(135deg, rgba(120, 53, 15, 0.7), rgba(69, 26, 3, 0.76));\n  box-shadow: 0 0 20px -8px rgba(245, 158, 11, 0.5);\n  color: #fde68a;\n  user-select: none;\n}\n\n.wallet-symbol {\n  display: grid;\n  width: 28px;\n  height: 28px;\n  flex: 0 0 auto;\n  place-items: center;\n  border: 1px solid rgba(251, 191, 36, 0.7);\n  border-radius: 50%;\n  background: rgba(245, 158, 11, 0.16);\n  font-weight: 900;\n}\n\n.wallet-copy {\n  align-items: flex-end;\n}\n\n.wallet-copy small {\n  color: rgba(253, 230, 138, 0.72);\n  font-size: 9px;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n}\n\n.wallet-copy strong {\n  font: 900 17px/1.1 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  white-space: nowrap;\n}\n\n.header-icon-button {\n  display: grid;\n  width: 40px;\n  height: 40px;\n  flex: 0 0 auto;\n  cursor: pointer;\n  place-items: center;\n  border-radius: 14px;\n  transition:\n    color 0.18s ease,\n    background-color 0.18s ease,\n    transform 0.18s ease;\n}\n\n.header-icon-button:hover {\n  background: rgba(30, 41, 59, 0.95);\n}\n\n.header-icon-button:active {\n  transform: scale(0.96);\n}\n\n/* 弹窗半透明玻璃面板 (Modal Glass Panel) */\n.glass-panel {\n  background: rgba(10, 15, 30, 0.94);\n  backdrop-filter: blur(24px);\n  -webkit-backdrop-filter: blur(24px);\n}\n\n/* 自定义纤细滚动条 (Custom Thin Scrollbar) */\n::-webkit-scrollbar {\n  width: 6px;\n  height: 6px;\n}\n::-webkit-scrollbar-track {\n  background: rgba(0, 0, 0, 0.2);\n}\n::-webkit-scrollbar-thumb {\n  background: rgba(100, 116, 139, 0.4);\n  border-radius: 9999px;\n  &:hover {\n    background: rgba(148, 163, 184, 0.6);\n  }\n}\n\n/* 角色与建档卡片通用底板 (Card Surface) */\n.card-surface {\n  background: linear-gradient(135deg, rgba(15, 23, 42, 0.85), rgba(10, 15, 30, 0.95));\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.5);\n}\n\n/* 顶部与底部修饰性微渐变分割线 */\n.card-divider-top {\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n/* 拟态光晕与弹窗阴影 (Glows & Shadows) */\n.shadow-glow-amber {\n  box-shadow: 0 0 24px -4px rgba(245, 158, 11, 0.35);\n}\n.shadow-glow-cyan {\n  box-shadow: 0 0 24px -4px rgba(6, 182, 212, 0.35);\n}\n.shadow-glow-emerald {\n  box-shadow: 0 0 24px -4px rgba(16, 185, 129, 0.35);\n}\n.shadow-glow-purple {\n  box-shadow: 0 0 24px -4px rgba(168, 85, 247, 0.35);\n}\n.shadow-glow-rose {\n  box-shadow: 0 0 24px -4px rgba(244, 63, 94, 0.35);\n}\n.shadow-modal {\n  box-shadow:\n    0 30px 80px -15px rgba(0, 0, 0, 0.95),\n    0 0 0 1px rgba(255, 255, 255, 0.08);\n}\n\n/* 正文段落排版 (Novel Text Standard · 严格绑定响应设置变量) */\n.novel-text {\n  font-size: var(--story-font-size, 17px) !important;\n  line-height: var(--story-line-height, 1.85) !important;\n  font-family: var(--story-font-family, ui-serif, Georgia, \"Songti SC\", serif) !important;\n  letter-spacing: 0.02em;\n}\n\n.novel-text p,\n.village-shell article p,\n.village-shell main p {\n  font-size: var(--story-font-size, 17px) !important;\n  line-height: var(--story-line-height, 1.85) !important;\n  font-family: var(--story-font-family, ui-serif, Georgia, \"Songti SC\", serif) !important;\n}\n\n/* 弹窗进入动画 (Modal Fade & Scale Animation) */\n.modal-enter {\n  animation: modalFadeIn 0.22s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n}\n\n@keyframes modalFadeIn {\n  from {\n    opacity: 0;\n    transform: scale(0.98) translateY(8px);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n/* 导航按钮悬浮放大微动 (Dock Button Micro-interaction) */\n.dock-btn {\n  transition: all 0.22s cubic-bezier(0.4, 0, 0.2, 1);\n  &:hover {\n    transform: scale(1.08) translateX(3px);\n  }\n}\n\n.game-dock {\n  position: absolute;\n  top: 50%;\n  left: 24px;\n  transform: translateY(-50%);\n}\n\n.dock-surface {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  padding: 12px;\n  border-radius: 24px;\n}\n\n.story-canvas {\n  padding-block: 32px;\n}\n\n.story-canvas--win