function extractJsonArray(source) {
    let start = -1;
    let depth = 0;
    let inString = false;
    let escaped = false;
    for (let index = 0; index < source.length; index++) {
        const character = source[index];
        if (inString) {
            if (escaped)
                escaped = false;
            else if (character === '\\')
                escaped = true;
            else if (character === '"')
                inString = false;
            continue;
        }
        if (character === '"') {
            inString = true;
            continue;
        }
        if (character === '[') {
            if (depth === 0)
                start = index;
            depth++;
        }
        else if (character === ']' && depth > 0) {
            depth--;
            if (depth === 0 && start >= 0)
                return source.slice(start, index + 1);
        }
    }
    return null;
}
export function readJsonPatch(candidate) {
    const updateBlock = extractUpdateBlock(candidate) ?? candidate;
    const taggedSource = updateBlock.match(/<JSONPatch\b[^>]*>([\s\S]*?)<\/JSONPatch\s*>/i)?.[1]?.trim();
    const fallbackSource = extractJsonArray(updateBlock
        .replace(/<Analysis\b[^>]*>[\s\S]*?<\/Analysis\s*>/gi, '')
        .replace(/```(?:json)?/gi, '')
        .replace(/<\/?(?:UpdateVariable|JSONPatch)\b[^>]*>/gi, ''));
    const source = taggedSource || fallbackSource;
    if (!source)
        throw new Error('辅助 API 回复中既没有 <JSONPatch>，也没有可识别的 JSON 操作数组');
    let parsed;
    try {
        parsed = JSON.parse(jsonrepair(source));
    }
    catch (error) {
        throw new Error(`JSONPatch 不是合法 JSON：${error instanceof Error ? error.message : String(error)}`, {
            cause: error,
        });
    }
    if (!Array.isArray(parsed))
        throw new Error('JSONPatch 必须是操作数组');
    const invalidEntries = [];
    const operations = parsed.flatMap((entry, index) => {
        if (_.isPlainObject(entry))
            return [entry];
        if (typeof entry === 'string' && entry.trim()) {
            try {
                const decoded = JSON.parse(jsonrepair(entry.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')));
                if (_.isPlainObject(decoded))
                    return [decoded];
            }
            catch (error) {
                invalidEntries.push(`第 ${index + 1} 项无法解码：${error instanceof Error ? error.message : String(error)}`);
                return [];
            }
        }
        invalidEntries.push(`第 ${index + 1} 项不是 JSON 对象`);
        return [];
    });
    if (invalidEntries.length > 0) {
        throw new Error(`JSONPatch 含有无法使用的操作：${invalidEntries.join('；')}`);
    }
    if (parsed.length > 0 && operations.length === 0) {
        throw new Error('JSONPatch 非空，但没有解析出任何有效操作');
    }
    return operations;
}
